    DIG_NIVELES={basico:["Re4","Mi4","Fa4","Fa♯4","Sol4","La4","Si4","Do5"],
      grave:["Si♭3","Si3","Do4","Do♯4","Re4","Mi♭4","Mi4","Fa4","Fa♯4","Sol4","Sol♯4","La4","Si♭4","Si4","Do5","Do♯5"],
      agudo:["Re5","Mi♭5","Mi5","Fa5","Fa♯5","Sol5","Sol♯5","La5","Si♭5","Si5","Do6","Do♯6"]},
    dig={nota:null,bien:0,total:0,t:null};
function digNueva(){clearTimeout(dig.t);var nivel=document.getElementById('dig-nivel').value,
    pool=nivel==='todo'?DIG_NIVELES.grave.concat(DIG_NIVELES.agudo):DIG_NIVELES[nivel];
  var n=pool[Math.floor(Math.random()*pool.length)];dig.nota=n;
  var opts=[n],resto=mezclar(pool.filter(function(x){return x!==n;}));while(opts.length<4&&resto.length)opts.push(resto.pop());mezclar(opts);
  document.getElementById('dig-svg').innerHTML=DIG[n];
  var cont=document.getElementById('dig-opts');cont.innerHTML='';
  opts.forEach(function(o){var b=document.createElement('button');b.textContent=o;b.onclick=function(){digResp(o,b);};cont.appendChild(b);});
  document.getElementById('dig-pent').innerHTML='';
  document.getElementById('dig-fb').textContent='¿Qué nota escrita da esta digitación?';}
function digResp(o,btn){if(!dig.nota)return;dig.total++;var ok=o===dig.nota;if(ok)dig.bien++;btn.className=ok?'ok':'ko';
  var conc=nombreDe(midiDe(dig.nota)-9);
  ABCJS.renderAbc('dig-pent','X:1\nL:1/1\nK:C clef=treble\n'+abcDe(dig.nota)+'|',{scale:1.2,staffwidth:120,paddingleft:10});
  document.getElementById('dig-fb').textContent=(ok?'✅ ¡Bien! ':'❌ Era '+dig.nota+'. ')+'Se escribe '+dig.nota+' y suena '+conc+' (concierto). Aciertos: '+dig.bien+'/'+dig.total;
  dig.nota=null;dig.t=setTimeout(digNueva,ok?1500:2800);}

// ---- Transposición: Mi♭ ----
var CLAVES_MAYORES=[['Do',0,'sin alteraciones'],['Re♭',1,'5 bemoles'],['Re',2,'2 sostenidos'],['Mi♭',3,'3 bemoles'],['Mi',4,'4 sostenidos'],['Fa',5,'1 bemol'],
                    ['Fa♯',6,'6 sostenidos'],['Sol',7,'1 sostenido'],['La♭',8,'4 bemoles'],['La',9,'3 sostenidos'],['Si♭',10,'2 bemoles'],['Si',11,'5 sostenidos']],
    ABC_CLAVE={'Do':'C','Re♭':'Db','Re':'D','Mi♭':'Eb','Mi':'E','Fa':'F','Fa♯':'F#','Sol':'G','La♭':'Ab','La':'A','Si♭':'Bb','Si':'B'};
function escritaDe(pc){return CLAVES_MAYORES[(pc+9)%12];}
function convertir(){var pc=parseInt(document.getElementById('conv-sel').value,10),c=CLAVES_MAYORES[pc],e=escritaDe(pc);
  document.getElementById('conv-res').innerHTML='Si el piano toca en <b>'+c[0]+' mayor</b> ('+c[2]+'), el saxo alto lee en <b>'+e[0]+' mayor</b> ('+e[2]+').';
  ABCJS.renderAbc('conv-pent','X:1\nL:1/1\nK:'+ABC_CLAVE[e[0]]+' clef=treble\nz|',{scale:1.2,staffwidth:200,paddingleft:10});}
var trans={ok:null,bien:0,total:0,t:null};
function transNueva(){clearTimeout(trans.t);var pc=Math.floor(Math.random()*12),c=CLAVES_MAYORES[pc],e=escritaDe(pc),dir=Math.random()<.6;
  var pregunta,resp,pool=CLAVES_MAYORES.map(function(x){return x[0];});
  if(dir){pregunta='El piano toca en <b>'+c[0]+' mayor</b>. ¿En qué tonalidad lee el saxo alto?';resp=e[0];}
  else{pregunta='El saxo alto lee en <b>'+e[0]+' mayor</b>. ¿En qué tonalidad suena (concierto)?';resp=c[0];}
  var opts=[resp],resto=mezclar(pool.filter(function(x){return x!==resp;}));while(opts.length<4)opts.push(resto.pop());mezclar(opts);
  trans.ok=resp;document.getElementById('trans-q').innerHTML=pregunta;
  var cont=document.getElementById('trans-opts');cont.innerHTML='';
  opts.forEach(function(o){var b=document.createElement('button');b.textContent=o+' mayor';b.onclick=function(){transResp(o,b);};cont.appendChild(b);});
  document.getElementById('trans-fb').textContent='';}
function transResp(o,btn){if(!trans.ok)return;trans.total++;var ok=o===trans.ok;if(ok)trans.bien++;btn.className=ok?'ok':'ko';
  document.getElementById('trans-fb').textContent=(ok?'✅ ¡Bien! ':'❌ Era '+trans.ok+' mayor. ')+'Aciertos: '+trans.bien+'/'+trans.total+'. Regla: el saxo alto escribe una sexta mayor por encima de lo que suena (añade 3 sostenidos).';
  trans.ok=null;trans.t=setTimeout(transNueva,ok?1300:2600);}

// ---- Afinador con micrófono (tono escrito del saxo alto) ----
function detectarTono(buf,sr){
  var n=buf.length,rms=0,i,tau;for(i=0;i<n;i++)rms+=buf[i]*buf[i];rms=Math.sqrt(rms/n);if(rms<0.008)return -1;
  var minLag=Math.floor(sr/1300),maxLag=Math.floor(sr/100),d=new Float32Array(maxLag+2),x,s;
  for(tau=1;tau<=maxLag;tau++){s=0;for(i=0;i<n-maxLag;i++){x=buf[i]-buf[i+tau];s+=x*x;}d[tau]=s;}
  var cm=new Float32Array(maxLag+2),run=0;cm[0]=1;for(tau=1;tau<=maxLag;tau++){run+=d[tau];cm[tau]=run>0?d[tau]*tau/run:1;}
  var est=-1;for(tau=Math.max(minLag,2);tau<maxLag;tau++){if(cm[tau]<0.15){while(tau+1<maxLag&&cm[tau+1]<cm[tau])tau++;est=tau;break;}}
  if(est<0)return -1;var a=cm[est-1],b=cm[est],c=cm[est+1],den=a-2*b+c,sh=den!==0?(a-c)/(2*den):0;return sr/(est+sh);}
function infoNota(frec,ref){var m=69+12*Math.log2(frec/ref),r=Math.round(m),cents=Math.round((m-r)*100);
  return {concierto:nombreDe(r),escrita:nombreDe(r+9),cents:cents};}
var af={ctx:null,an:null,buf:null,raf:null,stream:null,ult:[]};
function afIniciar(){
  var b=document.getElementById('af-btn');
  if(af.stream){afParar();return;}
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){document.getElementById('af-nota').textContent='—';document.getElementById('af-msg').textContent='Este navegador no permite usar el micrófono. Usa el tono de referencia o una aplicación de afinador.';return;}
  navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}}).then(function(st){
    af.stream=st;af.ctx=new (window.AudioContext||window.webkitAudioContext)();var src=af.ctx.createMediaStreamSource(st);
    af.an=af.ctx.createAnalyser();af.an.fftSize=4096;af.buf=new Float32Array(af.an.fftSize);src.connect(af.an);
    b.textContent='■ Parar el afinador';document.getElementById('af-msg').textContent='Toca una nota larga…';afBucle();
  }).catch(function(){document.getElementById('af-msg').textContent='No se ha podido usar el micrófono (permiso denegado o no disponible dentro de la plataforma). Usa el tono de referencia o una aplicación de afinador.';});}
function afParar(){cancelAnimationFrame(af.raf);if(af.stream){af.stream.getTracks().forEach(function(t){t.stop();});}
  if(af.ctx){try{af.ctx.close();}catch(e){}}af.stream=null;af.ctx=null;document.getElementById('af-btn').textContent='🎤 Activar el afinador';}
function afBucle(){
  if(!af.stream)return;af.an.getFloatTimeDomainData(af.buf);
  var f=detectarTono(af.buf,af.ctx.sampleRate),ref=parseFloat(document.getElementById('af-ref').value);
  if(f>0){af.ult.push(f);if(af.ult.length>5)af.ult.shift();var med=af.ult.slice().sort(function(a,b){return a-b;})[Math.floor(af.ult.length/2)],i=infoNota(med,ref);
    document.getElementById('af-nota').textContent=i.escrita;document.getElementById('af-conc').textContent='Suena '+i.concierto+' · '+med.toFixed(1)+' Hz';
    var c=Math.max(-50,Math.min(50,i.cents));document.getElementById('af-aguja').style.left=(50+c)+'%';
    var e=document.getElementById('af-cents');e.textContent=(i.cents>0?'+':'')+i.cents+' cents '+(Math.abs(i.cents)<=5?'✅ afinado':(i.cents>0?'· alto (saca la boquilla un poco o relaja la embocadura)':'· bajo (mete la boquilla un poco o apoya más el aire)'));
    e.style.color=Math.abs(i.cents)<=5?'#2e7d32':'#8a5a00';
  }else{af.ult=[];}
  af.raf=requestAnimationFrame(afBucle);}
var tono={ctx:null,osc:null,t:null};
function tonoRef(nombre){
  tonoParar();var ref=parseFloat(document.getElementById('af-ref').value),m=midiDe(nombre)-9,fr=ref*Math.pow(2,(m-69)/12);
  tono.ctx=new (window.AudioContext||window.webkitAudioContext)();var o=tono.ctx.createOscillator(),g=tono.ctx.createGain();
  o.type='triangle';o.frequency.value=fr;g.gain.setValueAtTime(0.0001,tono.ctx.currentTime);g.gain.exponentialRampToValueAtTime(0.35,tono.ctx.currentTime+0.05);
  o.connect(g).connect(tono.ctx.destination);o.start();tono.osc=o;
  document.getElementById('tono-msg').textContent='Suena '+nombreDe(m)+' de concierto ('+fr.toFixed(1)+' Hz): es la nota escrita '+nombre+'. Toca la tuya y compara.';
  tono.t=setTimeout(tonoParar,6000);}
function tonoParar(){clearTimeout(tono.t);if(tono.ctx){try{tono.osc.stop();tono.ctx.close();}catch(e){}tono.ctx=null;}}

// ---- Temporizador de práctica ----
var tm={t:null,resta:0};
function tmPintar(){var m=Math.floor(tm.resta/60),s=tm.resta%60;document.getElementById('tm-pant').textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;}
function tmIniciar(min){clearInterval(tm.t);tm.resta=min*60;tmPintar();document.getElementById('tm-msg').textContent='Tocando… ¡concéntrate!';
  tm.t=setInterval(function(){tm.resta--;tmPintar();if(tm.resta<=0){clearInterval(tm.t);document.getElementById('tm-msg').textContent='⏰ ¡Tiempo! Descansa los labios 5 minutos.';
    try{var c=new (window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator();o.frequency.value=880;o.connect(c.destination);o.start();o.stop(c.currentTime+0.4);}catch(e){}}},1000);}
function tmParar(){clearInterval(tm.t);document.getElementById('tm-msg').textContent='Parado.';}

function comoTodos(a){document.querySelectorAll('details.como').forEach(function(d){d.open=a;});}
// Autoevaluaciones
function checkAnswer(btn,ok,id){var p=btn.parentElement;p.querySelectorAll('.option').forEach(function(b){b.classList.remove('correct','incorrect')});
  btn.classList.add(ok?'correct':'incorrect');var fb=document.getElementById('fb-'+id);fb.textContent=ok?'✅ ¡Correcto! '+fb.getAttribute('data-ok'):'❌ No es correcto. Repasa el apartado e inténtalo de nuevo.';}
window.addEventListener('load',function(){dibujarPartituras();if(document.getElementById('conv-sel'))convertir();if(document.getElementById('met-beats'))metroPintar();});
